SELECT s.s_store_name, ca.ca_state, SUM(ss.ss_ext_sales_price) AS total_sales, AVG(ss.ss_net_profit) AS avg_profit FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk JOIN customer_address ca ON ss.ss_addr_sk = ca.ca_address_sk WHERE ss.ss_sold_date_sk BETWEEN 2452197 AND 2452264 AND s.s_state = 'NE' GROUP BY s.s_store_name, ca.ca_state HAVING SUM(ss.ss_ext_sales_price) > 4944.50 ORDER BY total_sales DESC LIMIT 5
